var i=`0149-piti`;var a=`world-0149`;var t=`AZ`;var s=`western-asia`;var o=4;var r=205;var l={en:`Piti`,ua:`Піті`};var g={en:`A classic dish from Azerbaijan, featuring lamb shank, yellow onion, bay leaf, canned chickpeas. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Азербайджан. Основні складники: гомілка ягняти, жовта цибуля, лавровий лист, консервований нут. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 140 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 140 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:140,i:[[`lamb-shank`,750,`g`],[`water`,1600,`ml`],[`yellow-onion`,180,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 60 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 60 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:60,i:[[`canned-chickpeas`,340,`g`],[`potato`,400,`g`],[`plum`,120,`g`],[`chestnut`,110,`g`],[`saffron-threads`,.2,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:2,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lavash`,170,`g`]]}];var d={slug:i,id:a,country:`AZ`,region:s,servings:4,minutes:205,title:l,text:g,steps:m};export{t as country,d as default,a as id,r as minutes,s as region,o as servings,i as slug,m as steps,g as text,l as title};